  "settings.appearance.colorsDesc": "Choisissez une palette de couleurs ou personnalisez les palettes de surface et d'accentuation.",
  "settings.appearance.stylesDesc": "Transformez la disposition visuelle, la forme des boutons, la géométrie et les matériaux de surface.",
  "settings.appearance.desc": "Choisissez un thème pour l’ensemble de l’application — couvre la barre supérieure, la barre latérale, les cartes et les accents. Les modifications s’appliquent instantanément.",
  "settings.accent.desc": "Teintez les boutons, liens et états actifs sans perdre votre thème. Se réinitialise sur l’accent intégré du thème lorsqu’il est effacé.",
  "settings.integrations.desc": "Connectez des comptes de boutiques externes pour importer vos jeux possédés, votre temps de jeu et vos succès dans GameIndex.",
  "settings.rockstar.desc": "Analysez les titres installés du Rockstar Games Launcher (GTA, Red Dead, Max Payne et plus) et lancez-les via le client Rockstar. Aucun compte requis.",
  "settings.rockstar.detected": "Rockstar Games Launcher détecté",
  "settings.rockstar.notInstalled": "Le Rockstar Games Launcher n’est pas installé — seuls les titres déjà sur le disque peuvent être détectés.",
  "settings.rockstar.localNote": "La détection est entièrement locale : GameIndex lit le registre de désinstallation Windows pour les titres Rockstar installés.",
  "settings.rockstar.scanBtn": "Analyser les jeux installés",
  "settings.ubisoft.desc": "Importez votre bibliothèque Ubisoft Connect — jeux installés et catalogue complet — et lancez des titres via le client Ubisoft Connect. Aucun compte requis.",
  "settings.ubisoft.detected": "Ubisoft Connect détecté",
  "settings.ubisoft.notInstalled": "Ubisoft Connect n’est pas installé — seuls les jeux déjà sur le disque peuvent être détectés via le registre.",
  "settings.ubisoft.localNote": "La détection est entièrement locale : GameIndex lit le registre de désinstallation Windows pour les titres installés et le cache Ubisoft Connect pour votre bibliothèque.",
  "settings.ubisoft.syncBtn": "Synchroniser la bibliothèque",
  "settings.integrations.footerNotice": "Plus d’intégrations à venir — itch.io et plus.",
  "settings.autoSync.desc": "Fréquence à laquelle GameIndex réimporte votre bibliothèque depuis Steam, Epic et GOG en arrière-plan.",
  "settings.historyRetention.desc": "Durée de conservation du nombre historique de joueurs Steam pour les graphiques de tendance de chaque page de jeu. Plus court = moins d’espace disque ; plus long = graphiques plus détaillés.",
  "settings.achievements.noSpoilersTitle": "Masquer la progression des succès (sans spoiler)",
  "settings.achievements.noSpoilersDesc": "Supprime les pourcentages de déverrouillage globaux et les anneaux de rareté de l’onglet Succès et de la page du jeu pour afficher une liste de contrôle propre.",
  "settings.achievements.localTitle": "Suivre les succès des jeux téléchargés / crackés",
  "settings.achievements.localDesc": "Surveille les fichiers de succès locaux des cracks et émulateurs (Goldberg, CODEX, RUNE, OnlineFix et plus) et déverrouille les succès pour les jeux hors Steam. Les détails sont récupérés anonymement.",
  "settings.discord.title": "Afficher votre jeu en cours sur Discord",
  "settings.discord.desc": "Publie un statut « Joue à X » sur votre profil Discord et le supprime lorsque le jeu se ferme.",
  "settings.downloads.notifyDesc": "Recevez une notification lorsqu’un téléchargement se termine afin de laisser les transferts tourner en arrière-plan.",
  "settings.downloads.bandwidthDesc": "Contrôlez la vitesse maximale utilisée pour le téléchargement et l’envoi de torrents de jeux.",
  "settings.downloads.blockedCount": "{count} domaine{s} bloqué{s}",
  "settings.downloads.blockedNone": "Aucun domaine bloqué",
  "settings.downloads.blockedDesc": "Les domaines répertoriés ici sont filtrés de chaque recherche de téléchargement — aucun résultat de ces hôtes n’apparaîtra dans la fenêtre de téléchargement. Un domaine par ligne.",
  "settings.downloads.sourcesDescStart": "Ajoutez des URL de sources au format JSON pour trouver des miroirs de téléchargement pour vos jeux. Les sources utilisent un format JSON compatible avec un",
  "settings.downloads.sourcesDescEnd": "tableau et sont enregistrées. Le bouton de téléchargement sur la page de n’importe quel jeu recherchera dans vos sources activées.",
  "settings.downloads.debridDesc": "Configurez un service Debrid (AllDebrid ou TorBox) pour télécharger des liens magnet torrent via des connexions HTTP directes à haute vitesse.",
  "settings.launcher.desc": "Décidez de ce que fait GameIndex au démarrage, lorsque vous lancez un jeu, et du comportement de la fenêtre elle-même.",
