  "setup.welcome.heading": "Vos jeux, une seule bibliothèque",
  "setup.welcome.intro": "GameIndex réunit toutes les boutiques dans une bibliothèque unique, pensée pour la manette — avec suivi du temps de jeu, succès, sauvegardes et un overlay en jeu.",
  "setup.welcome.f1": "Bibliothèque unifiée",
  "setup.welcome.f1Desc": "Steam, GOG, Epic, Rockstar, Ubisoft, Humble et les jeux ajoutés manuellement côte à côte.",
  "setup.welcome.f2": "Pensé manette",
  "setup.welcome.f2Desc": "Un mode Big Picture pour le canapé et une interface de bureau complète.",
  "setup.welcome.f3": "Overlay et capture",
  "setup.welcome.f3Desc": "Un HUD en jeu, des captures d'écran et l'enregistrement de replays.",
  "setup.welcome.f4": "Privé par défaut",
  "setup.welcome.f4Desc": "Vos données restent sur votre PC ; les fonctions en ligne sont optionnelles.",
  "setup.welcome.language": "Langue d'affichage",
  "setup.welcome.languageDesc": "S'applique immédiatement à toute l'application.",
  "setup.welcome.languageTip": "Change aussitôt tous les libellés de GameIndex. Vous pouvez changer de langue à tout moment dans Paramètres → Général.",
  "setup.appearance.theme": "Thème",
  "setup.appearance.themeDesc": "Choisissez un jeu de couleurs — cliquez pour l'apercevoir en direct.",
  "setup.appearance.themeTip": "Définit la palette de couleurs de l'application. Elle s'applique instantanément pour comparer les thèmes.",
  "setup.appearance.style": "Style d'interface",
  "setup.appearance.styleDesc": "Ajuste la forme et l'habillage de l'interface.",
  "setup.appearance.styleTip": "Contrôle la forme et les surfaces des composants (onglets, cartes, boutons), indépendamment du thème de couleurs.",
  "setup.appearance.density": "Densité de mise en page",
  "setup.appearance.densityTip": "« Simple » masque les widgets et onglets avancés pour un démarrage épuré ; « Complète » affiche tout.",
  "setup.appearance.simple": "Simple",
  "setup.appearance.simpleDesc": "Une mise en page épurée avec moins de widgets et d'onglets.",
  "setup.appearance.complete": "Complète",
  "setup.appearance.completeDesc": "Tous les widgets, badges et onglets sont visibles.",
  "setup.features.tabs": "Onglets de navigation",
  "setup.features.tabsDesc": "Choisissez les pages affichées dans la barre supérieure. Les onglets masqués peuvent être rétablis à tout moment dans les Paramètres.",
  "setup.features.tabsTooltip": "Affiche ou masque les pages de la navigation supérieure. Masquer un onglet ne supprime rien — il disparaît seulement de la barre.",
  "setup.features.tabTip": "Affiche ou masque l'onglet « {tab} » dans la barre de navigation supérieure.",
  "setup.features.masters": "Fonctions optionnelles",
  "setup.features.mastersDesc": "Activez ou désactivez des fonctions entières.",
  "setup.features.mastersTooltip": "Interrupteurs principaux pour les fonctions qui tournent en arrière-plan. Chacune peut aussi être modifiée plus tard dans les Paramètres.",
  "setup.features.saves": "Sauvegardes",
  "setup.features.savesDesc": "Sauvegardez et restaurez vos sauvegardes de jeu.",
  "setup.features.savesTip": "Crée des instantanés de vos fichiers de sauvegarde et peut les restaurer. Désactivé par défaut ; active l'onglet Sauvegardes.",
  "setup.features.overlay": "Overlay en jeu (HUD)",
  "setup.features.overlayDesc": "Un affichage par-dessus les jeux en cours.",
  "setup.features.overlayTip": "Affiche un HUD ouvrable par-dessus un jeu en cours (raccourci par défaut Shift+F1) : télémétrie, captures d'écran et guides. Désactivé par défaut.",
  "setup.features.capture": "Capture vidéo et replay",
  "setup.features.captureDesc": "Enregistrez des clips et gardez un tampon de replay.",
  "setup.features.captureTip": "Enregistre des clips de jeu et conserve un tampon de replay continu pour sauvegarder les derniers instants. Nécessite l'overlay activé.",
  "setup.features.discord": "Discord Rich Presence",
  "setup.features.discordDesc": "Affichez ce que vous jouez sur Discord.",
  "setup.features.discordTip": "Partage votre jeu en cours et votre temps de jeu sur votre profil Discord. Envoie des données à Discord, donc désactivé par défaut.",
  "setup.features.hardware": "Surveillance matérielle",
  "setup.features.hardwareDesc": "Suivez la charge et la température CPU/GPU.",
  "setup.features.hardwareTip": "Enregistre l'utilisation et la température du CPU et du GPU pendant les sessions pour les afficher ensuite en graphique.",
  "setup.features.achievements": "Suivi local des succès",
  "setup.features.achievementsDesc": "Détectez les succès des jeux non-Steam.",
  "setup.features.achievementsTip": "Surveille les fichiers de succès locaux (cracks/émulateurs) pour suivre les succès des jeux sans connexion Steam.",
  "setup.features.shelves": "Étagères intelligentes",
  "setup.features.shelvesDesc": "Regroupez votre bibliothèque en collections mises à jour automatiquement.",
  "setup.features.shelvesTip": "Les étagères à règles nommées apparaissent dans la barre latérale et en rangées épinglées sur l'accueil. Désactivez ceci pour masquer toutes les étagères.",
  "setup.libraries.heading": "Importer vos jeux",
  "setup.libraries.body": "GameIndex peut analyser votre disque pour trouver les jeux installés et récupérer votre bibliothèque Steam. Vous pouvez ajouter des dossiers manuellement à tout moment depuis la page Bibliothèque.",
  "setup.libraries.steamDetect": "Détecter automatiquement les jeux Steam installés",
  "setup.libraries.steamDetectTip": "Lorsque l'option est active, GameIndex associe les exécutables que vous ajoutez à des jeux Steam connus et remplit automatiquement leurs métadonnées.",
  "setup.libraries.addGame": "Ajouter un jeu",
  "setup.libraries.addGameTip": "Ouvre un sélecteur de fichier pour ajouter un seul jeu via son exécutable. GameIndex récupère ensuite sa jaquette et ses métadonnées.",
  "setup.libraries.scanFolder": "Analyser un dossier",
  "setup.libraries.scanFolderTip": "Analyse un dossier et ses sous-dossiers à la recherche d'exécutables de jeux, puis vous laisse vérifier et ajouter les résultats.",
  "setup.hardware.body": "GameIndex enregistre les FPS, l'utilisation CPU/GPU et les températures par session. Sur un système à plusieurs adaptateurs, choisissez la carte à mesurer.",
  "setup.hardware.gpu": "GPU à surveiller",
  "setup.hardware.gpuTip": "Sélectionne la carte graphique utilisée pour les relevés de température et d'utilisation. Choisissez celle qu'affiche aussi votre outil de surveillance.",
  "setup.hardware.gpuAuto": "Automatique (premier GPU)",
  "setup.hardware.gpuNone": "Aucun GPU compatible détecté.",
  "setup.hardware.refresh": "Détecter à nouveau",
  "setup.hardware.monitoring": "Enregistrement",
  "setup.hardware.monitoringTip": "Lorsque activé, la charge et la température CPU/GPU par session sont stockées pour être affichées en graphique. Désactivez pour économiser des ressources.",
  "setup.overlay.heading": "Outils en jeu",
  "setup.overlay.body": "Les deux sont désactivés par défaut. L'overlay s'ouvre par-dessus un jeu en cours ; l'enregistreur capture des clips en arrière-plan.",
  "setup.overlay.hudTip": "Affiche le HUD par-dessus les jeux en cours (raccourci par défaut Shift+F1) : télémétrie, captures d'écran et guides.",
  "setup.overlay.captureTip": "Permet d'enregistrer des clips et de sauvegarder les derniers instants grâce à un tampon de replay. Nécessite l'overlay activé.",
  "setup.overlay.hotkeyNote": "Appuyez sur Shift+F1 pendant qu'un jeu tourne pour ouvrir l'overlay.",
  "setup.overlay.unsupported": "La capture vidéo n'est pas prise en charge sur ce système.",
  "setup.startup.heading": "Démarrage et comportement de la fenêtre",
  "setup.startup.body": "Comment GameIndex se lance et ce que fait sa fenêtre.",
